import sys
from collections import deque

def bfs(x, y, table, visited, n, m):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(x, y, 0)])
    visited[x][y][0] = True
    count = 0
    while queue:
        cx, cy, step = queue.popleft()
        if step == 4:
            count += 1
            step = 0
        next_char = 'DIMAD'[step]
        for dx, dy in directions:
            nx, ny = cx + dx, cy + dy
            if 0 <= nx < n and 0 <= ny < m and table[nx][ny] == next_char and not visited[nx][ny][step]:
                visited[nx][ny][step] = True
                queue.append((nx, ny, step + 1))
    return count

def main():
    import sys
    input = sys.stdin.read().split()
    n, m = map(int, input[:2])
    table = [list(input[2 + i]) for i in range(n)]
    visited = [[[False] * 4 for _ in range(m)] for _ in range(n)]
    max_count = 0
    infinite = False
    for i in range(n):
        for j in range(m):
            if table[i][j] == 'D':
                count = bfs(i, j, table, visited, n, m)
                if count == float('inf'):
                    infinite = True
                max_count = max(max_count, count)
    if max_count == 0:
        print("Poor Dima!")
    elif infinite:
        print("Poor Inna!")
    else:
        print(max_count)

main()
